import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`bid-management`,heroTitle:`Master your bid pipeline in minutes`,heroSubtitle:`Perplexity Computer organizes your open bids, tracks sub outreach, and builds a daily-action bid calendar — automatically.`,hasInputUrl:!1,hasInputFile:!0,inputFileCta:`Upload your bid docs`,inputFileAccept:`.pdf,.doc,.docx,.xlsx,.xls,.csv`,inputFilePrefill:`Review the uploaded document and treat it as an active bid package, RFQ list, or subcontractor outreach tracker for a construction company. Then do the following:

1) Parse every open bid and organize them by submission deadline, scope of work, and priority level (high/medium/low based on deadline proximity and contract value).
2) Extract key addenda, scope clarifications, alternates, and special requirements from each bid package — flag anything ambiguous or conflicting.
3) Analyze subcontractor outreach status for each trade — identify which subs have been contacted, which have responded, which have gaps with no coverage, and which trades still need outreach.
4) Generate a master bid calendar dashboard showing every open bid on a timeline with daily action items — including addenda review dates, sub quote deadlines, internal review milestones, and final submission dates.
5) For bids within 7 days of deadline, flag all missing items — unsigned forms, outstanding sub quotes, insurance certs, bond requirements, and incomplete scope sheets.
6) Draft follow-up messages for unresponsive subcontractors, personalized by trade and bid.
7) Assemble a submission-day proposal checklist for each bid — every required document, signature, and deliverable in order — so nothing gets missed.

Deliver everything in a single organized dashboard updated with this morning's priorities.`,heroOverlaySteps:[`Parsing your bid documents, RFQs, and outreach trackers`,`Extracting deadlines, addenda, and scope clarifications from each package`,`Mapping subcontractor coverage gaps and outreach status by trade`,`Master bid calendar with daily action items — ready to execute`],generatingSteps:[`Analyzing the uploaded file to extract bids, deadlines, and sub outreach data`,`Designing an agent to organize bids by deadline, scope, and priority`,`Configuring addenda extraction, sub tracking, and gap analysis across every trade`,`Setting up your daily bid calendar dashboard with action items and deadline alerts`],featureSectionTitle:`From bid docs to command center`,featureCardTitles:[`Connects to your construction stack`,`Outputs you can build on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Google Drive, Gmail, Slack, Notion — Computer plugs into your tools so bid tracking, sub outreach, and document management work in one workflow.`,`Master bid calendar. Daily action items. Sub outreach gap reports. Follow-up drafts for unresponsive subs. Submission-day checklists for every open bid.`],capabilitySectionTitle:`Your bid desk, on autopilot`,capabilitySectionSubtitle:`Upload your bid docs, step away, come back to a prioritized action plan.`,capabilityCards:[{title:`Bid Organization`,description:`Computer can parse every open RFQ and bid package — sorting by deadline, scope, contract value, and priority so you see what matters first.`},{title:`Addenda Extraction`,description:`Computer can pull key addenda, scope clarifications, and spec changes from each bid package — and flag conflicts or ambiguities before they cost you.`},{title:`Sub Tracking`,description:`Computer can map subcontractor outreach by trade — who's been contacted, who's responded, and where you have dangerous coverage gaps.`},{title:`Connect Your Tools`,description:`Computer can read from Google Drive, Google Sheets, Gmail, Slack, and Notion — build workflows across your entire bid management stack.`},{title:`Remember & Learn`,description:`Computer can remember your preferred subs, past bid outcomes, and win rates — so every new bid benefits from your history.`},{title:`Monitor & Alert`,description:`Computer can check your bid pipeline every morning and flag approaching deadlines, missing documents, and unresponsive subs before it's too late.`}]});export{t as default};
